// Build Google Ads queries with proper date range
const items = $input.all();
const updatedItems = items.map((item) => {
  const accountId = item.json.account_id;
  const campaignIds = item.json.campaign_ids;
  const managerId = item.json.manager_id;

  // Calculate date range (last 7 days)
  const endDate = new Date();
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - 7);

  const formatDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const dateRangeClause = `segments.date BETWEEN '${formatDate(startDate)}' AND '${formatDate(endDate)}'`;
  const campaignFilter = `campaign.id IN (${campaignIds.join(',')})`;

  // Build queries object
  const queries = {
    campaign: `SELECT campaign.id, campaign.name, campaign.status, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.average_cpc, metrics.cost_per_conversion FROM campaign WHERE ${campaignFilter} AND ${dateRangeClause}`,

    keyword: `SELECT campaign.name, ad_group.name, ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.cost_per_conversion FROM keyword_view WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`,

    ad: `SELECT campaign.name, ad_group.name, ad_group_ad.ad.id, ad_group_ad.ad.type, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.cost_per_conversion FROM ad_group_ad WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`,

    search_terms: `SELECT search_term_view.search_term, segments.search_term_match_type, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr FROM search_term_view WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`
  };

  return {
    json: {
      account_id: item.json.account_id,
      account_name: item.json.account_name,
      target_cpl: item.json.target_cpl,
      weekly_budget: item.json.weekly_budget,
      campaign_ids: item.json.campaign_ids,
      manager_id: managerId,
      queries: queries,
      date_range: {
        start: formatDate(startDate),
        end: formatDate(endDate)
      }
    }
  };
});

return updatedItems;
